const items = $input.all();

if (items.length === 0) {
  return [];
}

const source = items[0];
const binary = source.binary ?? {};

const ignoredRootNames = new Set([
  "__MACOSX",
  ".DS_Store",
  "Thumbs.db",
]);

const groups = new Map();

for (const [binaryKey, file] of Object.entries(binary)) {
  const directory = String(file.directory ?? "")
    .replace(/\\/g, "/")
    .replace(/^\/+|\/+$/g, "");

  const fileName = String(file.fileName ?? "");

  if (!directory || !fileName) {
    continue;
  }

  const parts = directory
    .split("/")
    .map((part) => part.trim())
    .filter(Boolean);

  if (parts.length === 0) {
    continue;
  }

  if (
    parts.some(
      (part) =>
        part === ".." ||
        part === "." ||
        part.includes("\0")
    )
  ) {
    continue;
  }

  const firstLevelFolder = parts[0];

  if (
    ignoredRootNames.has(firstLevelFolder) ||
    firstLevelFolder.startsWith(".")
  ) {
    continue;
  }

  if (!groups.has(firstLevelFolder)) {
    groups.set(firstLevelFolder, {
      files: [],
      childFolders: new Set(),
    });
  }

  const group = groups.get(firstLevelFolder);

  group.files.push({
    binaryKey,
    file,
    directory,
    fileName,
  });

  if (
    parts.length >= 2 &&
    parts[1] !== "OG" &&
    parts[1] !== "__MACOSX" &&
    !parts[1].startsWith(".")
  ) {
    group.childFolders.add(parts[1]);
  }
}

const output = [];

for (const [firstLevelFolder, group] of groups.entries()) {
  const childFolders = [...group.childFolders];

  const productName =
    childFolders.length === 1
      ? childFolders[0]
      : firstLevelFolder;

  const productFolder =
    childFolders.length === 1
      ? `${firstLevelFolder}/${childFolders[0]}`
      : firstLevelFolder;

  const productBinary = {};

  for (const entry of group.files) {
    productBinary[entry.binaryKey] =
      entry.file;
  }

  output.push({
    json: {
      ...source.json,
      first_level_folder:
        firstLevelFolder,
      product_folder:
        productFolder,
      product_name:
        productName,
      detected_child_folders:
        childFolders,
      extracted_file_count:
        group.files.length,
    },
    binary: productBinary,
  });
}

output.sort((a, b) =>
  a.json.first_level_folder.localeCompare(
    b.json.first_level_folder,
    undefined,
    {
      numeric: true,
      sensitivity: "base",
    }
  )
);

return output;

const items = $input.all();

const allowedExtensions = new Set([
  "jpg",
  "jpeg",
  "png",
  "webp",
  "avif",
]);

const results = [];

for (const item of items) {
  const binary = item.binary ?? {};
  const candidates = [];

  for (const [binaryKey, file] of Object.entries(binary)) {
    const directory = String(file.directory ?? "")
      .replace(/\\/g, "/")
      .replace(/^\/+|\/+$/g, "");

    const fileName = String(file.fileName ?? "").trim();
    const mimeType = String(file.mimeType ?? "").toLowerCase();

    if (!fileName) {
      continue;
    }

    const pathParts = directory
      .split("/")
      .map((part) => part.trim())
      .filter(Boolean);

    const hasIgnoredFolder = pathParts.some((part) => {
      const value = part.toLowerCase();

      return (
        value === "og" ||
        value === "__macosx" ||
        value.startsWith(".")
      );
    });

    if (hasIgnoredFolder) {
      continue;
    }

    if (fileName.startsWith(".")) {
      continue;
    }

    const extension = String(
      file.fileExtension ??
      fileName.split(".").pop() ??
      ""
    )
      .toLowerCase()
      .replace(/^\./, "");

    if (!allowedExtensions.has(extension)) {
      continue;
    }

    if (
      file.fileType !== "image" &&
      !mimeType.startsWith("image/")
    ) {
      continue;
    }

    const numericPrefixMatch =
      fileName.match(/^(\d+)/);

    const numericPrefix =
      numericPrefixMatch
        ? Number(numericPrefixMatch[1])
        : Number.MAX_SAFE_INTEGER;

    candidates.push({
      binaryKey,
      file,
      fileName,
      directory,
      extension,
      mimeType,
      numericPrefix,
    });
  }

  candidates.sort((a, b) => {
    if (a.numericPrefix !== b.numericPrefix) {
      return a.numericPrefix - b.numericPrefix;
    }

    return a.fileName.localeCompare(
      b.fileName,
      undefined,
      {
        numeric: true,
        sensitivity: "base",
      }
    );
  });

  const selected = candidates.slice(0, 6);
  const selectedBinary = {};
  const manifest = [];

  selected.forEach((entry, index) => {
    const selectedKey = `image_${index + 1}`;

    selectedBinary[selectedKey] =
      entry.file;

    manifest.push({
      order: index + 1,
      binary_key: selectedKey,
      source_binary_key:
        entry.binaryKey,
      file_name:
        entry.fileName,
      directory:
        entry.directory,
      extension:
        entry.extension,
      mime_type:
        entry.mimeType,
      bytes:
        entry.file.bytes ?? null,
    });
  });

  results.push({
    json: {
      ...item.json,
      candidate_image_count:
        candidates.length,
      selected_image_count:
        selected.length,
      ignored_image_count:
        Math.max(
          0,
          Object.keys(binary).length -
            selected.length
        ),
      selected_images:
        manifest,
      image_selection_needs_review:
        selected.length === 0,
    },
    binary: selectedBinary,
  });
}

return results;

const items = $input.all();
const output = [];

for (const item of items) {
  const selected = Array.isArray(item.json.selected_images)
    ? item.json.selected_images
    : [];

  for (const image of selected) {
    const sourceKey = image.binary_key;
    const file = item.binary?.[sourceKey];

    if (!file) {
      continue;
    }

    output.push({
      json: {
        ...item.json,
        ai_image_order: image.order,
        ai_source_file_name: image.file_name,
        ai_source_directory: image.directory,
        ai_source_mime_type: image.mime_type,
      },
      binary: {
        data: file,
      },
    });
  }
}

return output;

const aiItems = $input.all();
const sourceItems = $("Prepare Images for AI").all();

const groups = new Map();

function getText(value) {
  if (typeof value === "string") return value;
  if (value === null || value === undefined) return "";
  try {
    return JSON.stringify(value);
  } catch {
    return String(value);
  }
}

function extractAiPayload(json) {
  const candidates = [
    json?.content,
    json?.text,
    json?.output_text,
    json?.output,
    json?.response,
    json?.message?.content,
  ];

  for (const candidate of candidates) {
    if (candidate !== undefined && candidate !== null) {
      return getText(candidate);
    }
  }

  return getText(json);
}

for (let i = 0; i < aiItems.length; i++) {
  const aiItem = aiItems[i];
  const source = sourceItems[i]?.json ?? {};
  const key = String(
    source.first_level_folder ??
    source.product_folder ??
    source.product_name ??
    i
  );

  if (!groups.has(key)) {
    groups.set(key, {
      source,
      analyses: [],
    });
  }

  groups.get(key).analyses.push({
    image_order:
      source.ai_image_order ?? i + 1,
    file_name:
      source.ai_source_file_name ?? null,
    analysis:
      extractAiPayload(aiItem.json),
  });
}

const output = [];

for (const { source, analyses } of groups.values()) {
  analyses.sort(
    (a, b) =>
      Number(a.image_order) -
      Number(b.image_order)
  );

  output.push({
    json: {
      id: source.id,
      organization_id:
        source.organization_id,
      store_id:
        source.store_id ?? null,
      name: source.name,
      original_filename:
        source.original_filename,
      input_storage_path:
        source.input_storage_path,
      first_level_folder:
        source.first_level_folder,
      product_folder:
        source.product_folder,
      product_name:
        source.product_name,
      selected_image_count:
        source.selected_image_count ??
        analyses.length,
      selected_images:
        source.selected_images ?? [],
      visual_evidence:
        analyses,
      visual_evidence_count:
        analyses.length,
    },
  });
}

output.sort((a, b) =>
  String(
    a.json.first_level_folder ?? ""
  ).localeCompare(
    String(
      b.json.first_level_folder ?? ""
    ),
    undefined,
    {
      numeric: true,
      sensitivity: "base",
    }
  )
);

return output;

const aiItems = $input.all();
const sourceItems =
  $("Aggregate Visual Evidence").all();

const allowed = new Set([
  "Sofa",
  "Sofa Bed",
  "Recliner",
  "Armchair",
  "Dining Chair",
  "Ottoman",
  "Bench",
  "Stool",
  "Bed",
  "Headboard",
  "Kids Bed",
  "Office Chair",
  "Unclassified",
]);

function parseClassification(value) {
  const visited = new Set();

  function walk(node) {
    if (node === null || node === undefined) {
      return null;
    }

    if (typeof node === "string") {
      const cleaned = node
        .replace(/^\s*```(?:json)?/i, "")
        .replace(/```\s*$/i, "")
        .trim();

      try {
        return walk(JSON.parse(cleaned));
      } catch {
        return null;
      }
    }

    if (typeof node !== "object") {
      return null;
    }

    if (visited.has(node)) {
      return null;
    }

    visited.add(node);

    if (
      typeof node.category === "string" &&
      node.confidence !== undefined
    ) {
      return node;
    }

    if (Array.isArray(node)) {
      for (const entry of node) {
        const found = walk(entry);
        if (found) return found;
      }
      return null;
    }

    for (const child of Object.values(node)) {
      const found = walk(child);
      if (found) return found;
    }

    return null;
  }

  return walk(value);
}

const output = [];

for (
  let i = 0;
  i < aiItems.length;
  i++
) {
  const source =
    sourceItems[i]?.json ?? {};

  const parsed =
    parseClassification(
      aiItems[i]?.json ?? {}
    );

  const category =
    parsed &&
    allowed.has(parsed.category)
      ? parsed.category
      : "Unclassified";

  let confidence =
    Number(parsed?.confidence);

  if (
    !Number.isFinite(confidence)
  ) {
    confidence = 0;
  }

  confidence = Math.max(
    0,
    Math.min(
      100,
      Math.round(confidence)
    )
  );

  const needsReview =
    category === "Unclassified" ||
    confidence < 70;

  output.push({
    json: {
      ...source,
      category,
      category_confidence:
        confidence,
      category_classification_basis:
        Array.isArray(
          parsed?.classification_basis
        )
          ? parsed.classification_basis
          : [],
      category_uncertainties:
        Array.isArray(
          parsed?.uncertainties
        )
          ? parsed.uncertainties
          : [],
      category_classification_valid:
        Boolean(parsed) &&
        allowed.has(category),
      category_needs_review:
        needsReview,
    },
  });
}

return output;

const products = $input.all();
const templateItems = $("Load Active Templates").all();

const templates = templateItems
  .map((item) => item.json ?? {})
  .filter((row) =>
    row.id &&
    row.organization_id &&
    row.category &&
    row.status === "active"
  );

const byCategory = new Map();

for (const template of templates) {
  const category = String(template.category);

  const existing = byCategory.get(category);

  if (
    !existing ||
    Number(template.version ?? 0) >
      Number(existing.version ?? 0)
  ) {
    byCategory.set(category, template);
  }
}

return products.map((item) => {
  const row = item.json ?? {};
  const category = String(
    row.category ?? "Unclassified"
  );

  const template =
    category === "Unclassified"
      ? null
      : byCategory.get(category) ?? null;

  const templateMissing = !template;

  return {
    json: {
      ...row,
      template_used: Boolean(template),
      template_missing: templateMissing,
      template_id: template?.id ?? null,
      template_version:
        template?.version ?? null,
      template_content_md:
        template?.content_md ?? null,
      needs_review:
        Boolean(
          row.category_needs_review
        ) || templateMissing,
      review_reasons: [
        ...(
          Array.isArray(
            row.review_reasons
          )
            ? row.review_reasons
            : []
        ),
        ...(
          row.category_needs_review
            ? ["category_confidence_or_classification"]
            : []
        ),
        ...(
          templateMissing
            ? ["category_template_missing"]
            : []
        ),
      ].filter(
        (value, index, array) =>
          array.indexOf(value) === index
      ),
    },
  };
});

const aiItems = $input.all();
const sourceItems = $("Resolve Category Template").all();

const allowedTypes = new Set([
  "Sofa",
  "Sofa Bed",
  "Recliner",
  "Armchair",
  "Dining Chair",
  "Ottoman",
  "Bench",
  "Stool",
  "Bed",
  "Headboard",
  "Kids Bed",
  "Office Chair",
  "Unclassified",
]);

const controlledSections = [
  "Warranty",
  "Sizes Available",
  "Customisation Options",
  "Delivery Info",
  "Exclusions",
];

function parseAi(value) {
  const visited = new Set();

  function walk(node) {
    if (node === null || node === undefined) {
      return null;
    }

    if (typeof node === "string") {
      const cleaned = node
        .replace(/^\s*```(?:json)?/i, "")
        .replace(/```\s*$/i, "")
        .trim();

      try {
        return walk(JSON.parse(cleaned));
      } catch {
        return null;
      }
    }

    if (typeof node !== "object") {
      return null;
    }

    if (visited.has(node)) {
      return null;
    }

    visited.add(node);

    if (
      Array.isArray(node.highlights) &&
      typeof node.seo_paragraph === "string" &&
      Array.isArray(node.key_features) &&
      typeof node.seo_title === "string" &&
      typeof node.seo_description === "string"
    ) {
      return node;
    }

    if (Array.isArray(node)) {
      for (const entry of node) {
        const found = walk(entry);
        if (found) return found;
      }
      return null;
    }

    for (const child of Object.values(node)) {
      const found = walk(child);
      if (found) return found;
    }

    return null;
  }

  return walk(value);
}

function escapeHtml(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function normalizeHeading(value) {
  return String(value ?? "")
    .toLowerCase()
    .replace(/[^a-z0-9 ]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function canonicalHeading(value) {
  const key = normalizeHeading(value);

  const aliases = new Map([
    ["warranty", "Warranty"],
    ["sizes available", "Sizes Available"],
    ["available sizes", "Sizes Available"],
    ["sizes", "Sizes Available"],
    ["customisation options", "Customisation Options"],
    ["customization options", "Customisation Options"],
    ["customisation", "Customisation Options"],
    ["customization", "Customisation Options"],
    ["delivery info", "Delivery Info"],
    ["delivery information", "Delivery Info"],
    ["delivery", "Delivery Info"],
    ["exclusions", "Exclusions"],
    ["exclusion", "Exclusions"],
  ]);

  return aliases.get(key) ?? null;
}

function extractControlledSections(markdown) {
  const result = Object.fromEntries(
    controlledSections.map((name) => [name, ""])
  );

  if (!markdown) return result;

  const lines = String(markdown)
    .replace(/\r\n/g, "\n")
    .split("\n");

  let current = null;
  const buckets = Object.fromEntries(
    controlledSections.map((name) => [name, []])
  );

  for (const line of lines) {
    const headingMatch = line.match(/^#{1,6}\s+(.+?)\s*$/);

    if (headingMatch) {
      current = canonicalHeading(headingMatch[1]);
      continue;
    }

    if (current) {
      buckets[current].push(line);
    }
  }

  for (const name of controlledSections) {
    result[name] = buckets[name]
      .join("\n")
      .trim();
  }

  return result;
}

function inlineMarkdown(text) {
  let value = escapeHtml(text);

  value = value
    .replace(/\*\*(.+?)\*\*/g, "<strong>$1</strong>")
    .replace(/__(.+?)__/g, "<strong>$1</strong>")
    .replace(/\*(.+?)\*/g, "<em>$1</em>")
    .replace(/_(.+?)_/g, "<em>$1</em>");

  return value;
}

function markdownToHtml(markdown) {
  const input = String(markdown ?? "").trim();

  if (!input) return "";

  const lines = input.split("\n");
  const output = [];
  let listType = null;
  let paragraph = [];

  function flushParagraph() {
    if (paragraph.length) {
      output.push(
        "<p>" +
        inlineMarkdown(paragraph.join(" ").trim()) +
        "</p>"
      );
      paragraph = [];
    }
  }

  function closeList() {
    if (listType) {
      output.push(`</${listType}>`);
      listType = null;
    }
  }

  for (const rawLine of lines) {
    const line = rawLine.trim();

    if (!line) {
      flushParagraph();
      closeList();
      continue;
    }

    const unordered = line.match(/^[-*+]\s+(.+)$/);
    const ordered = line.match(/^\d+[.)]\s+(.+)$/);

    if (unordered || ordered) {
      flushParagraph();

      const wanted = unordered ? "ul" : "ol";

      if (listType !== wanted) {
        closeList();
        output.push(`<${wanted}>`);
        listType = wanted;
      }

      output.push(
        "<li>" +
        inlineMarkdown((unordered || ordered)[1]) +
        "</li>"
      );
      continue;
    }

    if (listType) {
      closeList();
    }

    paragraph.push(line);
  }

  flushParagraph();
  closeList();

  return output.join("\n");
}

function slugify(value) {
  return String(value ?? "")
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .replace(/-+/g, "-");
}

function clampHandle(value) {
  return slugify(value)
    .slice(0, 60)
    .replace(/-+$/g, "");
}

function wordCount(value) {
  const text = String(value ?? "").trim();
  return text ? text.split(/\s+/).length : 0;
}

function hasForbiddenLeather(value) {
  const text = String(value ?? "");

  if (/\bLeatherette\b/.test(text)) {
    return /\bleather\b/i.test(
      text.replace(/\bLeatherette\b/g, "")
    );
  }

  return /leather/i.test(text);
}

function collectStrings(value) {
  if (Array.isArray(value)) {
    return value
      .map((v) => String(v ?? "").trim())
      .filter(Boolean);
  }

  return [];
}

const usedHandles = new Set();
const output = [];

for (let i = 0; i < sourceItems.length; i++) {
  const source = sourceItems[i]?.json ?? {};
  const generated = parseAi(aiItems[i]?.json ?? {});

  const productName = String(source.product_name ?? "").trim();
  const category = allowedTypes.has(source.category)
    ? source.category
    : "Unclassified";

  const title =
    `${productName} ${category} Custom Crafted to Order`
      .replace(/\s+/g, " ")
      .trim();

  const highlights = collectStrings(
    generated?.highlights
  ).slice(0, 5);

  const keyFeatures = collectStrings(
    generated?.key_features
  ).slice(0, 6);

  const seoParagraph = String(
    generated?.seo_paragraph ?? ""
  ).trim();

  const seoTitle = String(
    generated?.seo_title ?? ""
  ).trim();

  const seoDescription = String(
    generated?.seo_description ?? ""
  ).trim();

  const attributeExtraction = String(
    source.attribute_extraction ?? ""
  ).trim();

  const jackpotSelected = collectStrings(
    source.jackpot_selected
  ).slice(0, 2);

  const topListSelected = collectStrings(
    source.top_list_selected
  ).slice(0, 6);

  const metaTitleTopTerms = collectStrings(
    source.meta_title_top_terms
  ).slice(0, 2);

  const metaDescriptionExtraTopTerms = collectStrings(
    source.meta_description_extra_top_terms
  ).slice(0, 2);

  const productWord = category;

  const handle = slugify([
    jackpotSelected[0] ?? "",
    productWord,
    attributeExtraction,
    productName,
    jackpotSelected[1] ?? "",
  ].filter(Boolean).join("-"));

  usedHandles.add(handle);

  const sections = extractControlledSections(
    source.template_content_md
  );

  const highlightsHtml =
    "<ul>" +
    highlights
      .map((item) => `<li>${escapeHtml(item)}</li>`)
      .join("") +
    "</ul>";

  const featuresHtml =
    keyFeatures.length
      ? "<ul>" +
        keyFeatures
          .map((item) => `<li>${escapeHtml(item)}</li>`)
          .join("") +
        "</ul>"
      : "";

  const bodyHtml = [
    "<!-- ---- Product Highlights ---- -->",
    "<h3>Product Highlights</h3>",
    highlightsHtml,
    `<p>${escapeHtml(seoParagraph)}</p>`,
    "<!-- ----- Warranty ----- -->",
    "<h3>Warranty</h3>",
    markdownToHtml(sections["Warranty"]),
    "<!-- ---- Sizes Available ---- -->",
    "<h3>Sizes Available</h3>",
    markdownToHtml(sections["Sizes Available"]),
    "<!-- ---- Customisation Options ---- -->",
    "<h3>Customisation Options</h3>",
    markdownToHtml(sections["Customisation Options"]),
    "<!-- ----- Key Features ----- -->",
    "<h3>Key Features</h3>",
    featuresHtml,
    "<!-- ---- Delivery Info ---- -->",
    "<h3>Delivery Info</h3>",
    markdownToHtml(sections["Delivery Info"]),
    "<!-- ---- Exclusions ---- -->",
    "<h3>Exclusions</h3>",
    markdownToHtml(sections["Exclusions"]),
  ]
    .filter((part) => part !== "")
    .join("\n");

  const generationWarnings = [];

  if (!generated) {
    generationWarnings.push("ai_content_missing_or_invalid");
  }

  if (highlights.length !== 5) {
    generationWarnings.push("product_highlights_must_equal_5");
  }

  if (
    wordCount(seoParagraph) < 80 ||
    wordCount(seoParagraph) > 150
  ) {
    generationWarnings.push("seo_paragraph_word_count");
  }

  if (
    seoParagraph.length < 500 ||
    seoParagraph.length > 1000
  ) {
    generationWarnings.push("seo_paragraph_character_count");
  }

  if (
    seoTitle.length < 30 ||
    seoTitle.length > 60
  ) {
    generationWarnings.push("seo_title_length");
  }

  if (
    seoDescription.length < 100 ||
    seoDescription.length > 155
  ) {
    generationWarnings.push("seo_description_length");
  }

  if (title.length > 150) {
    generationWarnings.push("title_length");
  }

  if (
    jackpotSelected.length !== 2 ||
    jackpotSelected[0]?.toLowerCase() === jackpotSelected[1]?.toLowerCase()
  ) {
    generationWarnings.push("jackpot_selection_invalid");
  }

  if (
    !/^[A-Za-z]+$/.test(attributeExtraction)
  ) {
    generationWarnings.push("attribute_extraction_must_be_one_word");
  }

  if (
    topListSelected.length < 4
  ) {
    generationWarnings.push("top_list_selection_invalid");
  }

  if (
    handle.length > 60
  ) {
    generationWarnings.push("url_slug_length");
  }

  if (
    handle.length < 1 ||
    handle.length > 60 ||
    !/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(handle)
  ) {
    generationWarnings.push("handle_format");
  }

  const copyForLeatherCheck = [
    title,
    ...highlights,
    seoParagraph,
    ...keyFeatures,
    seoTitle,
    seoDescription,
  ].join(" ");

  if (hasForbiddenLeather(copyForLeatherCheck)) {
    generationWarnings.push("forbidden_leather_wording");
  }

  const missingControlledSections =
    controlledSections.filter(
      (name) => !sections[name]
    );

  if (
    source.template_used &&
    missingControlledSections.length
  ) {
    generationWarnings.push(
      "active_template_missing_controlled_sections"
    );
  }

  const needsReview =
    Boolean(source.needs_review) ||
    generationWarnings.length > 0;

  const reviewReasons = [
    ...(
      Array.isArray(source.review_reasons)
        ? source.review_reasons
        : []
    ),
    ...generationWarnings,
  ].filter(
    (value, index, array) =>
      array.indexOf(value) === index
  );

  output.push({
    json: {
      ...source,
      handle,
      url_slug: handle,
      attribute_extraction: attributeExtraction,
      jackpot_selected: jackpotSelected,
      top_list_selected: topListSelected,
      meta_title_top_terms: metaTitleTopTerms,
      meta_description_extra_top_terms: metaDescriptionExtraTopTerms,
      title,
      body_html: bodyHtml,
      type: category,
      seo_title: seoTitle,
      seo_description: seoDescription,
      seo_paragraph: seoParagraph,
      product_highlights: highlights,
      key_features: keyFeatures,
      vision_analysis:
        source.visual_evidence ?? [],
      template_sections_found:
        controlledSections.filter(
          (name) => Boolean(sections[name])
        ),
      template_sections_missing:
        missingControlledSections,
      generation_warnings:
        generationWarnings,
      needs_review: needsReview,
      review_reasons: reviewReasons,
    },
  });
}

return output;

const items = $input.all();

const allowedTypes = new Set([
