];

const unsupportedClaimPatterns = [
  ["premium_quality", /\bpremium\s+quality\b/i],
  ["luxury_quality", /\bluxury\s+quality\b/i],
  ["ergonomic", /\bergonomic\b/i],
  ["orthopaedic", /\borthopaedic\b|\borthopedic\b/i],
  ["durable", /\bdurable\b/i],
  ["long_lasting", /\blong[-\s]?lasting\b/i],
  ["stain_resistant", /\bstain[-\s]?resistant\b/i],
  ["water_resistant", /\bwater[-\s]?resistant\b/i],
  ["scratch_resistant", /\bscratch[-\s]?resistant\b/i],
  ["pet_friendly", /\bpet[-\s]?friendly\b/i],
  ["child_safe", /\bchild[-\s]?safe\b/i],
  ["eco_friendly", /\beco[-\s]?friendly\b/i],
  ["sustainable", /\bsustainable\b/i],
  ["imported", /\bimported\b/i],
  ["handcrafted", /\bhandcrafted\b/i],
