  ["hardwood_frame", /\bhardwood\s+frame\b/i],
];

function addError(errors, code) {
  if (!errors.includes(code)) {
    errors.push(code);
  }
}

function normalize(value) {
  return String(value ?? "").trim();
}

function phraseIncluded(text, phrase) {
  return normalize(text).toLowerCase().includes(
    normalize(phrase).toLowerCase()
  );
}

function distinctCaseInsensitive(values) {
  const normalized = values.map((value) =>
    normalize(value).toLowerCase()
  );
  return new Set(normalized).size === normalized.length;
}

function wordCount(value) {
  const text = normalize(value);
  return text ? text.split(/\s+/).length : 0;
}

function arrayOfStrings(value) {
  return Array.isArray(value) &&
    value.every(
      (entry) =>
        typeof entry === "string" &&
        entry.trim().length > 0
    );
}

function uniqueNormalized(values) {
  const seen = new Set();

  for (const value of values) {
    const normalized = String(value)
      .toLowerCase()
      .replace(/\s+/g, " ")
      .trim();

    if (seen.has(normalized)) {
      return false;
    }

    seen.add(normalized);
  }

  return true;
}

function countOccurrences(text, needle) {
  if (!needle) return 0;

  let count = 0;
  let position = 0;

  while (true) {
    const index = text.indexOf(needle, position);

    if (index === -1) {
      break;
    }

    count++;
    position = index + needle.length;
  }

  return count;
}

function escapeHtml(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function containsForbiddenLeatherWord(value) {
  const matches =
    String(value ?? "").match(/[A-Za-z-]*leather[A-Za-z-]*/gi) ?? [];

  return matches.some(
    (word) =>
      word.toLowerCase() !== "leatherette"
  );
}

function containsAnyLeatherWord(value) {
  return /leather/i.test(String(value ?? ""));
}

function exactSetMatch(a, b) {
  if (a.length !== b.length) {
    return false;
  }

  const left = a
    .map((value) =>
      String(value)
        .toLowerCase()
        .replace(/\s+/g, " ")
        .trim()
    )
    .sort();

  const right = b
    .map((value) =>
      String(value)
        .toLowerCase()
        .replace(/\s+/g, " ")
        .trim()
    )
    .sort();

  return left.every(
    (value, index) =>
      value === right[index]
  );
}

const handleCounts = new Map();

for (const item of items) {
  const handle = normalize(item.json?.handle);

  if (handle) {
    handleCounts.set(
