}

return items.map((item) => {
  const row = item.json ?? {};
  const errors = [];

  const productName =
    normalize(row.product_name);

  const category =
    allowedTypes.has(row.category)
      ? row.category
      : "Unclassified";

  const expectedTitle =
    `${productName} ${category} Custom Crafted to Order`
      .replace(/\s+/g, " ")
      .trim();

  const handle =
    normalize(row.handle);

  const title =
    normalize(row.title);

  const bodyHtml =
    String(row.body_html ?? "");

  const seoTitle =
    normalize(row.seo_title);

  const seoDescription =
    normalize(row.seo_description);

  const seoParagraph =
    normalize(row.seo_paragraph);

  const highlights =
    Array.isArray(row.product_highlights)
      ? row.product_highlights
      : [];

  const keyFeatures =
    Array.isArray(row.key_features)
      ? row.key_features
      : [];

  const attributeExtraction =
    normalize(row.attribute_extraction);

  const jackpotSelected =
    Array.isArray(row.jackpot_selected)
      ? row.jackpot_selected.map(normalize).filter(Boolean)
      : [];

  const topListSelected =
    Array.isArray(row.top_list_selected)
      ? row.top_list_selected.map(normalize).filter(Boolean)
      : [];

  const metaTitleTopTerms =
    Array.isArray(row.meta_title_top_terms)
      ? row.meta_title_top_terms.map(normalize).filter(Boolean)
      : [];

  const metaDescriptionExtraTopTerms =
    Array.isArray(row.meta_description_extra_top_terms)
      ? row.meta_description_extra_top_terms.map(normalize).filter(Boolean)
      : [];

  const sofaConfiguration = normalize(row.sofa_configuration);
  const sofaConfigurationConfidence = Math.max(0, Math.min(100, Number(row.sofa_configuration_confidence ?? 0) || 0));
  const productConfiguration = normalize(row.product_configuration);
  const productConfigurationConfidence = Math.max(0, Math.min(100, Number(row.product_configuration_confidence ?? 0) || 0));

  if (!productName) {
    addError(
      errors,
      "product_name_missing"
    );
  }

  const expectedSeoHandle = String([
    jackpotSelected[0] ?? "",
    category,
    attributeExtraction,
    productName,
    jackpotSelected[1] ?? "",
  ].filter(Boolean).join("-"))
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .replace(/-+/g, "-");

  if (
    jackpotSelected.length !== 2 ||
    !distinctCaseInsensitive(jackpotSelected)
  ) {
    addError(errors, "jackpot_selection_invalid");
  }

  const productNameLower = productName.toLowerCase();
  const categoryLower = category.toLowerCase();

  if (
    jackpotSelected.some((term) => {
      const lower = term.toLowerCase();
      return (
        lower.includes(categoryLower) ||
        (productNameLower && lower.includes(productNameLower))
      );
    })
  ) {
    addError(errors, "jackpot_contains_product_word_or_title");
  }

  if (
    topListSelected.some((term) =>
      jackpotSelected.some(
        (jackpot) =>
          term.toLowerCase() === jackpot.toLowerCase()
      )
    )
  ) {
    addError(errors, "top_list_duplicates_jackpot");
  }

  if (
    !attributeExtraction ||
    !/^[A-Za-z]+$/.test(attributeExtraction)
  ) {
    addError(errors, "attribute_extraction_invalid");
  }

  if (
    topListSelected.length < 4 ||
    !distinctCaseInsensitive(topListSelected)
  ) {
    addError(errors, "top_list_selection_invalid");
  }

  if (handle !== expectedSeoHandle) {
    addError(errors, "url_slug_formula_mismatch");
  }

  if (
    metaTitleTopTerms.length < 1 ||
    metaTitleTopTerms.length > 2 ||
    !distinctCaseInsensitive(metaTitleTopTerms) ||
    !metaTitleTopTerms.every((term) =>
      topListSelected.some(
        (candidate) =>
          candidate.toLowerCase() === term.toLowerCase()
      )
    ) ||
    metaTitleTopTerms.some((term) =>
      jackpotSelected.some(
        (jackpot) =>
          jackpot.toLowerCase() === term.toLowerCase()
      )
    )
  ) {
    addError(errors, "meta_title_top_terms_invalid");
  }

  if (
    metaDescriptionExtraTopTerms.length < 1 ||
    metaDescriptionExtraTopTerms.length > 2 ||
    !distinctCaseInsensitive(metaDescriptionExtraTopTerms) ||
    !metaDescriptionExtraTopTerms.every((term) =>
      topListSelected.some(
        (candidate) =>
          candidate.toLowerCase() === term.toLowerCase()
      )
    ) ||
    metaDescriptionExtraTopTerms.some((term) =>
      metaTitleTopTerms.some(
        (used) =>
          used.toLowerCase() === term.toLowerCase()
      ) ||
      jackpotSelected.some(
        (jackpot) =>
          jackpot.toLowerCase() === term.toLowerCase()
      )
    )
  ) {
    addError(errors, "meta_description_extra_terms_invalid");
  }

  if (
    jackpotSelected.some(
      (term) => !phraseIncluded(seoTitle, term)
    ) ||
    metaTitleTopTerms.some(
      (term) => !phraseIncluded(seoTitle, term)
    )
  ) {
    addError(errors, "meta_title_required_terms_missing");
  }

  if (
    jackpotSelected.some(
      (term) => !phraseIncluded(seoDescription, term)
    ) ||
    metaTitleTopTerms.some(
      (term) => !phraseIncluded(seoDescription, term)
    ) ||
    metaDescriptionExtraTopTerms.some(
      (term) => !phraseIncluded(seoDescription, term)
    )
  ) {
    addError(errors, "meta_description_required_terms_missing");
  }

  if (
    !handle ||
    handle.length > 60 ||
    !/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(handle)
  ) {
    addError(
      errors,
      "handle_invalid"
    );
  }

  if (
    handle &&
    (handleCounts.get(handle) ?? 0) > 1
  ) {
    addError(
      errors,
      "handle_not_unique_within_job"
    );
  }

  if (title !== expectedTitle) {
    addError(
      errors,
      "title_formula_mismatch"
    );
  }

  if (title.length > 150) {
    addError(
      errors,
      "title_exceeds_150_characters"
    );
  }

  if (
    !allowedTypes.has(row.type) ||
    row.type !== category
  ) {
    addError(
      errors,
      "type_invalid_or_mismatched"
    );
  }

  const confidence =
    Number(row.category_confidence);

  if (
    !Number.isFinite(confidence) ||
    confidence < 0 ||
    confidence > 100
  ) {
    addError(
      errors,
      "category_confidence_invalid"
    );
  }

  if (
    category === "Unclassified" &&
    !row.needs_review
  ) {
    addError(
      errors,
      "unclassified_must_need_review"
    );
  }

  if (
    Number.isFinite(confidence) &&
    confidence < 70 &&
    !row.needs_review
  ) {
    addError(
      errors,
      "low_confidence_must_need_review"
    );
  }

  if (
    !arrayOfStrings(highlights) ||
    highlights.length !== 5
  ) {
    addError(
      errors,
      "product_highlights_must_equal_5"
    );
  } else if (
    !uniqueNormalized(highlights)
  ) {
    addError(
      errors,
      "product_highlights_not_distinct"
    );
  }

  if (
    keyFeatures.length > 0 &&
    !arrayOfStrings(keyFeatures)
  ) {
    addError(
      errors,
      "key_features_invalid"
    );
  }

  if (
    highlights.length > 0 &&
    keyFeatures.length > 0 &&
    exactSetMatch(
      highlights,
      keyFeatures
    )
  ) {
    addError(
      errors,
      "key_features_duplicate_all_highlights"
    );
  }

  const paragraphWords =
    wordCount(seoParagraph);

  if (
    paragraphWords < 80 ||
    paragraphWords > 150
  ) {
    addError(
      errors,
      "seo_paragraph_word_count"
    );
  }

  if (
    seoParagraph.length < 500 ||
    seoParagraph.length > 1000
  ) {
    addError(
      errors,
      "seo_paragraph_character_count"
    );
  }

  if (
    seoTitle.length < 30 ||
    seoTitle.length > 60
  ) {
    addError(
      errors,
      "seo_title_length"
    );
  }

  if (
    seoDescription.length < 100 ||
    seoDescription.length > 155
  ) {
    addError(
      errors,
      "seo_description_length"
    );
  }

  if (category === "Sofa") {
    const specificConfigPattern = /\b(?:[1-4]\s*seater\s+sofa|sectional\s+sofa|l[\s-]?shaped\s+sofa|sofa\s+with\s+lounger|corner\s+sofa)\b/i;
    const reliableConfig = sofaConfiguration && sofaConfiguration !== "unknown" && sofaConfiguration !== "not_applicable" && sofaConfigurationConfidence >= 75;

    if (!reliableConfig && specificConfigPattern.test(seoDescription)) {
      addError(errors, "seo_description_unverified_sofa_configuration");
    }

    if (
      reliableConfig &&
      sofaConfiguration !== "sofa set" &&
      !phraseIncluded(seoDescription, sofaConfiguration)
    ) {
      addError(errors, "seo_description_confirmed_sofa_configuration_missing");
    }
  }

  const reliableProductConfiguration = productConfiguration && productConfiguration.toLowerCase() !== "unknown" && productConfigurationConfidence >= 75;

  const riskyConfigurationPatterns = [
    /\b(?:single|double|queen|king)\s+(?:size\s+)?bed\b/i,
    /\b(?:[1-4]\s*seater)\b/i,
    /\b(?:sectional|l[\s-]?shaped|corner)\s+sofa\b/i,
    /\bsofa\s+with\s+lounger\b/i,
    /\bstorage\s+(?:bed|ottoman|bench)\b/i,
    /\b(?:bunk|loft|canopy|house)\s+bed\b/i,
    /\b(?:recliner|reclining)\s+(?:chair|sofa)\b/i,
    /\bswivel\s+(?:chair|office\s+chair)\b/i,
  ];

  if (!reliableProductConfiguration && riskyConfigurationPatterns.some((pattern) => pattern.test(seoDescription))) {
    addError(errors, "seo_description_unverified_product_configuration");
  }

  if (
    reliableProductConfiguration &&
    category !== "Sofa" &&
    !phraseIncluded(seoDescription, productConfiguration)
  ) {
    addError(errors, "seo_description_confirmed_product_configuration_missing");
  }

  const generatedCopy = [
    title,
    ...highlights,
    seoParagraph,
    ...keyFeatures,
    seoTitle,
    seoDescription,
  ].join(" ");

  if (
    containsAnyLeatherWord(
      generatedCopy
    )
  ) {
    addError(
      errors,
      "generated_copy_contains_unverified_leather_wording"
    );
  }

  if (
    containsForbiddenLeatherWord(
      row.template_content_md
    ) ||
    containsForbiddenLeatherWord(
      bodyHtml
    )
  ) {
    addError(
      errors,
      "forbidden_leather_wording"
    );
  }

  for (
    const [claim, pattern]
    of unsupportedClaimPatterns
  ) {
    if (pattern.test(generatedCopy)) {
      addError(
        errors,
        `unsupported_claim_${claim}`
      );
    }
  }

  if (
    /\b\d+(?:\.\d+)?\s*(?:mm|cm|metres?|meters?|inches?|inch|ft|feet)\b/i.test(
      generatedCopy
    ) ||
    /\b\d+(?:\.\d+)?\s*["”]\b/.test(
      generatedCopy
    )
  ) {
    addError(
      errors,
      "unsupported_measurement_claim"
    );
  }

  if (
    Boolean(row.template_missing) ||
    !Boolean(row.template_used)
  ) {
    addError(
      errors,
      "category_template_missing"
    );
  }

  if (
    row.template_used &&
    (
      !row.template_id ||
      !Number.isInteger(
        Number(row.template_version)
      ) ||
      !normalize(
        row.template_content_md
      )
    )
  ) {
    addError(
      errors,
      "template_metadata_invalid"
    );
  }

  if (
    row.template_used &&
    Array.isArray(
      row.template_sections_missing
    ) &&
    row.template_sections_missing.length > 0
  ) {
    addError(
      errors,
      "controlled_template_section_missing"
    );
  }

  const comments =
    bodyHtml.match(
      /<!--(?:.|\n|\r)*?-->/g
    ) ?? [];

  if (
    comments.length !==
      requiredComments.length ||
    !requiredComments.every(
      (comment, index) =>
        comments[index] === comment
    )
  ) {
    addError(
      errors,
      "body_section_comments_invalid_or_out_of_order"
    );
  }

  for (const comment of requiredComments) {
    if (
      countOccurrences(
        bodyHtml,
        comment
      ) !== 1
    ) {
      addError(
        errors,
        "body_section_comment_count_invalid"
      );
      break;
    }
  }

  const escapedParagraph =
    escapeHtml(seoParagraph);

  const paragraphBeforeWarranty =
    `<p>${escapedParagraph}</p>\n<!-- ----- Warranty ----- -->`;

  if (
    !bodyHtml.includes(
      paragraphBeforeWarranty
    )
  ) {
    addError(
      errors,
      "seo_paragraph_not_immediately_before_warranty"
    );
  }

  if (
    /<!--[^>]*\bcare\b[^>]*-->/i.test(
      bodyHtml
    ) ||
    /<h[1-6][^>]*>\s*care\b/i.test(
      bodyHtml
    )
  ) {
    addError(
      errors,
      "care_section_forbidden"
    );
  }

  const expectedHeadings = [
    "Product Highlights",
    "Warranty",
    "Sizes Available",
    "Customisation Options",
    "Key Features",
    "Delivery Info",
    "Exclusions",
  ];

  const headingMatches = [
    ...bodyHtml.matchAll(
      /<h3[^>]*>(.*?)<\/h3>/gi
    ),
  ].map((match) =>
    String(match[1])
      .replace(/<[^>]*>/g, "")
      .trim()
  );

  if (
    headingMatches.length !==
      expectedHeadings.length ||
    !expectedHeadings.every(
      (heading, index) =>
        headingMatches[index] === heading
    )
  ) {
    addError(
      errors,
      "body_headings_invalid_or_out_of_order"
    );
  }

  const priorWarnings =
    Array.isArray(
      row.generation_warnings
    )
      ? row.generation_warnings
      : [];

  for (const warning of priorWarnings) {
    addError(
      errors,
      `generation_warning:${warning}`
    );
  }

  const validationPassed =
    errors.length === 0;

  const needsReview =
    Boolean(row.needs_review) ||
    !validationPassed;

  const reviewReasons = [
    ...(
      Array.isArray(
        row.review_reasons
      )
        ? row.review_reasons
        : []
    ),
    ...errors,
  ].filter(
    (value, index, array) =>
      array.indexOf(value) === index
  );

  return {
    json: {
      ...row,
      validation_passed:
        validationPassed,
      validation_errors:
        errors,
      needs_review:
        needsReview,
      review_reasons:
        reviewReasons,
      validation_summary: {
        error_count:
          errors.length,
        handle_valid:
          !errors.includes(
            "handle_invalid"
          ) &&
          !errors.includes(
            "handle_not_unique_within_job"
          ),
        title_valid:
          !errors.includes(
            "title_formula_mismatch"
          ) &&
          !errors.includes(
            "title_exceeds_150_characters"
          ),
        body_valid:
          !errors.some(
            (error) =>
              error.startsWith(
                "body_"
              ) ||
              error ===
                "seo_paragraph_not_immediately_before_warranty" ||
              error ===
                "care_section_forbidden"
          ),
        seo_valid:
          !errors.some(
            (error) =>
              error.startsWith(
                "seo_"
              )
          ),
        template_valid:
          !errors.some(
            (error) =>
              error.includes(
                "template"
              )
          ),
      },
    },
  };
});

const rows = $("Prepare Product Rows").all().map((item) => item.json ?? {});

const jobId = $("Normalize Request").first().json.job_id;
const organizationId = $("Normalize Request").first().json.organization_id;

const totalProducts = rows.length;
const approvedProducts = rows.filter((row) => row.status === "approved").length;
const reviewProducts = rows.filter((row) => row.status === "review").length;
const failedProducts = rows.filter((row) => row.status === "failed").length;
const processedProducts = approvedProducts + reviewProducts + failedProducts;

const hasReview = reviewProducts > 0 || failedProducts > 0;
const finalStatus = hasReview ? "review" : "completed";
const currentStage = hasReview ? "review_required" : "completed";

return [{
  json: {
    job_id: jobId,
    organization_id: organizationId,
    total_products: totalProducts,
    processed_products: processedProducts,
    approved_products: approvedProducts,
    review_products: reviewProducts,
    failed_products: failedProducts,
    status: finalStatus,
    current_stage: currentStage,
    progress: 100,
    completed_at: new Date().toISOString(),
  },
}];

const aiItems = $input.all();
const sourceItems = $("Normalize Category Result").all();

function parseSeoSignals(value) {
  const visited = new Set();

  function walk(node) {
    if (node === null || node === undefined) return null;

    if (typeof node === "string") {
      const cleaned = node
        .replace(/^\s*```(?:json)?/i, "")
        .replace(/```\s*$/i, "")
        .trim();

      try {
        return walk(JSON.parse(cleaned));
      } catch {
        return null;
      }
    }

    if (typeof node !== "object") return null;
    if (visited.has(node)) return null;
    visited.add(node);

    if (
      typeof node.attribute_extraction === "string" &&
      Array.isArray(node.jackpot_selected) &&
      Array.isArray(node.top_list_selected)
    ) {
      return node;
    }

    if (Array.isArray(node)) {
      for (const entry of node) {
        const found = walk(entry);
        if (found) return found;
      }
      return null;
    }

    for (const child of Object.values(node)) {
      const found = walk(child);
      if (found) return found;
    }

    return null;
  }

  return walk(value);
}

return aiItems.map((item, index) => {
  const source = sourceItems[index]?.json ?? {};
  const parsed = parseSeoSignals(item.json ?? {});

  return {
    json: {
      ...source,
      attribute_extraction: String(parsed?.attribute_extraction ?? "").trim(),
      jackpot_selected: Array.isArray(parsed?.jackpot_selected)
        ? parsed.jackpot_selected.map(v => String(v ?? "").trim()).filter(Boolean).slice(0, 2)
        : [],
      top_list_selected: Array.isArray(parsed?.top_list_selected)
        ? parsed.top_list_selected.map(v => String(v ?? "").trim()).filter(Boolean).slice(0, 6)
        : [],
      meta_title_top_terms: Array.isArray(parsed?.meta_title_top_terms)
        ? parsed.meta_title_top_terms.map(v => String(v ?? "").trim()).filter(Boolean).slice(0, 2)
        : [],
      meta_description_extra_top_terms: Array.isArray(parsed?.meta_description_extra_top_terms)
        ? parsed.meta_description_extra_top_terms.map(v => String(v ?? "").trim()).filter(Boolean).slice(0, 2)
        : [],
      sofa_configuration: String(parsed?.sofa_configuration ?? (source.category === "Sofa" ? "unknown" : "not_applicable")).trim(),
      sofa_configuration_confidence: Math.max(0, Math.min(100, Number(parsed?.sofa_configuration_confidence ?? 0) || 0)),
      product_configuration: String(parsed?.product_configuration ?? "unknown").trim(),
      product_configuration_confidence: Math.max(0, Math.min(100, Number(parsed?.product_configuration_confidence ?? 0) || 0)),
      seo_image_analysis_valid: Boolean(parsed),
      seo_image_analysis_needs_review: !parsed,
    },
  };
});
